			1, 3, 5, 7, 9, 11: begin
				f_acc_t <= acc_t[state[3:1]];
				v <= state[3:1];
			end
		endcase
		case (state)
			3, 5, 7: begin
				_st_out[v] <= f__st_out;
				p_t_out[v] <= f_p_t_out;
				ps__out[v] <= f_ps__out;
				pst_out[v] <= f_pst_out;
			end
			9, 11, 13:
				if (DUAL) begin
					_st_out[v] <= f__st_out;
					p_t_out[v] <= f_p_t_out;
					ps__out[v] <= f_ps__out;
					pst_out[v] <= f_pst_out;
				end
		endcase
	end
	wire [17:0] faudio;
	function automatic signed [21:0] sv2v_cast_22_signed;
		input reg signed [21:0] inp;
		sv2v_cast_22_signed = inp;
	endfunction
	sid_filter sid_filter(
		.clk(clk),
		.state(state[2:0]),
		.mode(mode[n]),
		.F0(F0),
		.Res_Filt(Filter_Res_Filt[n]),
		.Mode_Vol(Filter_Mode_Vol[n]),
		.voice1(voice_1[n]),
		.voice2(voice_2[n]),
		.voice3(voice_3[n]),
		.ext_in(sv2v_cast_22_signed($signed({(n ? ext_in_r : ext_in_l), 3'b000}))),
		.audio(faudio)
	);
	always @(posedge clk) begin : sv2v_autoblock_2
		reg [17:0] audio0;
		if (state == 8)
			audio0 <= faudio;
		if (state == 15) begin
			audio[n] <= faudio;
			audio[0] <= audio0;
		end
	end
	assign data_out = (cs[0] ? bus_data[0] : bus_data[N - 1]);
	assign audio_l = audio[0];
	assign audio_r = audio[N - 1];
endmodule
