					sp_shiftreg = sdr;
				end
				else if (!cnt_out_r && cnt_out) begin
					if (cnt_pulsecnt == 3'h7) begin
						icr3 <= 1'b1;
						sp_transmit <= 1'b0;
					end
					{sp_out_reg, sp_shiftreg} = {sp_shiftreg, 1'b0};
				end
			end
		end
	always @(posedge clk) begin : sv2v_autoblock_2
		reg cra6_prev;
		if (!res_n) begin
			cnt_in_r <= 1'b1;
			cnt_in_prev <= 1'b1;
			cnt_out_r <= 1'b1;
			cnt_out <= 1'b1;
			cnt_pulsecnt <= 3'h0;
			cra6_prev <= 1'b0;
		end
		else if (phi2_p) begin
			cra6_prev <= cra[6];
			cnt_in_r <= cnt_in;
			cnt_in_prev <= cnt_in_r;
			cnt_out <= cnt_out_r;
			if (cra[6] != cra6_prev)
				cnt_pulsecnt <= 3'h0;
			if ((cra[6] ? !cnt_out_r && cnt_out : !cnt_in_r && cnt_in_prev))
				cnt_pulsecnt <= cnt_pulsecnt + 1'b1;
			if (!cra[6])
				cnt_out_r <= 1'b1;
			else if (timerAoverflow)
				cnt_out_r <= ~(sp_transmit & cnt_out_r);
		end
	end
	wire [4:0] icr_adj = {icr[4:2], timer_b_int, icr[0]};
	always @(posedge clk) begin : sv2v_autoblock_3
		reg [7:0] imr_reg;
		if (!res_n) begin
			imr <= 5'h00;
			imr_reg <= 0;
			irq_n <= 1'b1;
			int_reset <= 0;
		end
		else begin
			if (wr && (rs == 4'hd))
				imr_reg <= db_in;
			if (rd && (rs == 4'hd))
				int_reset <= 1;
			if (phi2_p | mode) begin
				imr <= (imr_reg[7] ? imr | imr_reg[4:0] : imr & ~imr_reg[4:0]);
				irq_n <= (irq_n ? ~|(imr & icr_adj) : irq_n);
			end
			if (phi2_p & int_reset) begin
				irq_n <= 1;
				int_reset <= 0;
			end
		end
	end
endmodule